import React, { Component } from 'react';
import moment from 'moment';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth, requestHeaderPUTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import {
    CButton,
    CCard,
    CCardBody,
    CCol,
    CContainer,
    CInput,
    CInputGroup,
    CInputGroupPrepend,
    CInputGroupText,
    CRow,
} from '@coreui/react';
import { Modal, ModalBody, ModalHeader } from 'reactstrap';
import Select from 'react-select';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import MaterialReactTable from 'material-react-table';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "InstagramProfile.js";

const initialState = {
    isLoaded: false,
    loadingModalVisible: false,
    loadingModalState: 0,
    failureModalVisible: false,
    profileDetails: null,
    reelListData: [],
    page: 1,
    size: 20,
    totalPages: 0,
    totalElements: 0,
    search: '',
    selectedTags: [],   // tag names chosen from this profile's tags to filter reels by
    tagMatchMode: 'OR', // 'OR' = any tag, 'AND' = all tags
    viewReelModalVisible: false,
    viewReelUrl: null,
    viewReelFileName: '',
    uploadingProfilePic: false,
    editingProfile: false,
    savingProfile: false,
    editForm: {},
};

const reelTableColumnData = [
    {
        accessorKey: 'id',
        header: 'ID',
        size: 60,
    },
    {
        accessorKey: 'thumbnailBase64',
        header: 'Thumbnail',
        size: 220,
        enableSorting: false,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue
                ? <img src={renderedCellValue} alt="reel" style={{ width: '200px', height: '112px', borderRadius: '4px', objectFit: 'contain', display: 'block' }} />
                : '—'
        ),
    },
    {
        // Combined column: upload date, then shortcode (links to Instagram), then caption.
        accessorKey: 'details',
        header: 'Details',
        size: 340,
        enableSorting: false,
        Cell: ({ row }) => {
            const reel = row.original;
            const instagramUrl = reel.link ? reel.link : null;
            return (
                <div style={{ maxWidth: '340px' }}>
                    <div style={{ fontSize: '15px', color: '#888' }}>
                        {reel.uploadDate
                            ? reel.uploadDate + ' ' + moment(reel.uploadDate).format('ddd')
                            : '—'}
                    </div>
                    <div style={{ fontWeight: 'bold' }}>
                        {reel.shortcode
                            ? (instagramUrl
                                ? <a href={instagramUrl} target="_blank" rel="noopener noreferrer">{reel.shortcode}</a>
                                : reel.shortcode)
                            : '—'}
                    </div>
                    <div
                        title={reel.caption}
                        style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
                    >
                        {reel.caption || '—'}
                    </div>
                    <div style={{ fontSize: '12px', color: '#555', whiteSpace: 'nowrap' }}>
                        <span>👁 {reel.viewCount ?? 0}</span>
                        <span style={{ marginLeft: '12px' }}>❤️ {reel.likeCount ?? 0}</span>
                        <span style={{ marginLeft: '12px' }} title="Downloaded">{reel.downloaded ? '[ ⬇️ ✅ ]' : '[ ⬇️ ❌ ]'}</span>
                    </div>
                    <div style={{ fontSize: '12px', color: '#555', whiteSpace: 'normal', marginTop: '2px' }}>
                        <span>🏷️ Tags: </span>
                        {Array.isArray(reel.tags) && reel.tags.length > 0
                            ? reel.tags.map((tag, i) => (
                                <span
                                    key={'tag-' + i}
                                    style={{
                                        display: 'inline-block',
                                        background: '#edf2f7',
                                        color: '#2d3748',
                                        borderRadius: '10px',
                                        padding: '1px 8px',
                                        marginRight: '4px',
                                        marginBottom: '2px',
                                        fontSize: '11px',
                                    }}
                                >
                                    {tag}
                                </span>
                            ))
                            : <span style={{ color: '#aaa' }}>—</span>}
                    </div>
                </div>
            );
        },
    },
    {
        accessorKey: 'collaboratorLink',
        header: 'Collab',
        size: 160,
        enableSorting: false,
        Cell: ({ row }) => {
            const reel = row.original;
            const hasCollab = reel.collaboratorLink || reel.collaboratorProfileId != null;
            if (!hasCollab) {
                return '—';
            }
            return (
                <span style={{ whiteSpace: 'nowrap' }}>
                    {reel.collaboratorLink && (
                        <a href={reel.collaboratorLink} target="_blank" rel="noopener noreferrer">Collab</a>
                    )}
                    {reel.collaboratorLink && reel.collaboratorProfileId != null && <span>&nbsp;|&nbsp;</span>}
                    {reel.collaboratorProfileId != null && (
                        <a
                            href={window.location.origin + '/#/instagram/profile/' + reel.collaboratorProfileId}
                            target="_blank"
                            rel="noopener noreferrer"
                        >
                            Collab Profile
                        </a>
                    )}
                </span>
            );
        },
    },
    {
        accessorKey: 'createdOn',
        header: 'Added On',
        size: 180,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue ? moment(renderedCellValue).format('YYYY/MM/DD HH:mm:ss ddd') : '—'
        ),
    },
];

class InstagramProfile extends Component {

    constructor(props) {
        super(props);
        this.state = JSON.parse(JSON.stringify(initialState));
    }

    resetStateToDefault() {
        this.setState(JSON.parse(JSON.stringify(initialState)));
    }

    getInternalProfileId() {
        return this.props.match.params.internalProfileId;
    }

    componentDidMount() {
        document.title = "Instagram Profile Details";
        this.fetchProfileDetails();
        this.fetchReelList();
    }

    reloadData = () => {
        this.fetchProfileDetails();
        this.fetchReelList();
    }

    fetchProfileDetails() {
        const internalProfileId = this.getInternalProfileId();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/profile/' + internalProfileId;
        const userData = getUserDataFromLocalStorage();

        Logger(FILE_NAME, "fetchProfileDetails", "", "internalProfileId", internalProfileId);

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ failureModalVisible: true });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({ failureModalVisible: true });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchProfileDetails", "FETCH_1", "result", result);
                this.setState({
                    profileDetails: result.data,
                    isLoaded: true,
                });
            },
            (error) => {
                Logger(FILE_NAME, "fetchProfileDetails", "FETCH_1", "error", error);
                this.setState({ failureModalVisible: true, isLoaded: true });
            }
        );
    }

    handleProfilePicSelected = (event) => {
        const file = event.target.files && event.target.files[0];
        // reset the input so selecting the same file again still triggers onChange
        event.target.value = '';
        if (!file) {
            return;
        }
        if (!file.type.startsWith('image/')) {
            alert('Please select an image file.');
            return;
        }

        const reader = new FileReader();
        reader.onload = () => {
            // reader.result is a data URI: "data:image/png;base64,AAAA..."
            this.updateProfilePic(reader.result);
        };
        reader.onerror = () => {
            Logger(FILE_NAME, "handleProfilePicSelected", "", "error", reader.error);
            this.setState({ failureModalVisible: true });
        };
        reader.readAsDataURL(file);
    }

    updateProfilePic(profilePicBase64) {
        this.setState({ uploadingProfilePic: true });
        this.saveProfile({ profilePicBase64 })
            .finally(() => this.setState({ uploadingProfilePic: false }));
    }

    // Builds the request body from the current profile plus any overrides, PUTs it,
    // and updates profileDetails on success. Returns a promise.
    saveProfile(overrides = {}) {
        const profile = this.state.profileDetails;
        if (!profile) {
            return Promise.resolve();
        }

        const internalProfileId = this.getInternalProfileId();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/profile/' + internalProfileId;
        const userData = getUserDataFromLocalStorage();

        // Send all backend-allowed editable fields, applying any overrides.
        const reqData = {
            instagramId: profile.instagramId,
            fullName: profile.fullName,
            bio: profile.bio,
            followersCount: profile.followersCount,
            followingCount: profile.followingCount,
            accountCreationDate: profile.accountCreationDate,
            ...overrides,
        };
        Logger(FILE_NAME, "saveProfile", "", "reqData", reqData);

        return fetch(API_URL, requestHeaderPUTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ failureModalVisible: true });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({ failureModalVisible: true });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then((result) => {
            Logger(FILE_NAME, "saveProfile", "FETCH_1", "result", result);
            this.setState({ profileDetails: result.data });
            return result.data;
        });
    }

    handleEditProfile = () => {
        const profile = this.state.profileDetails || {};
        this.setState({
            editingProfile: true,
            editForm: {
                instagramId: profile.instagramId != null ? profile.instagramId : '',
                fullName: profile.fullName != null ? profile.fullName : '',
                bio: profile.bio != null ? profile.bio : '',
                followersCount: profile.followersCount != null ? profile.followersCount : '',
                followingCount: profile.followingCount != null ? profile.followingCount : '',
                accountCreationDate: profile.accountCreationDate != null ? profile.accountCreationDate : '',
            },
        });
    }

    handleCancelEditProfile = () => {
        this.setState({ editingProfile: false, editForm: {} });
    }

    handleEditFormChange = (field) => (event) => {
        const value = event.target.value;
        this.setState((prevState) => ({
            editForm: { ...prevState.editForm, [field]: value },
        }));
    }

    handleSaveProfile = () => {
        const form = this.state.editForm;

        // Normalise numeric fields: blank -> null, else Number.
        const toNumberOrNull = (v) => (v === '' || v == null ? null : Number(v));
        const overrides = {
            instagramId: form.instagramId === '' ? null : form.instagramId,
            fullName: form.fullName === '' ? null : form.fullName,
            bio: form.bio === '' ? null : form.bio,
            followersCount: toNumberOrNull(form.followersCount),
            followingCount: toNumberOrNull(form.followingCount),
            accountCreationDate: form.accountCreationDate === '' ? null : form.accountCreationDate,
        };

        this.setState({ savingProfile: true });
        this.saveProfile(overrides)
            .then(() => this.setState({ editingProfile: false, editForm: {} }))
            .catch((error) => Logger(FILE_NAME, "handleSaveProfile", "", "error", error))
            .finally(() => this.setState({ savingProfile: false }));
    }

    callProcessDownloadedApi() {
        const internalProfileId = this.getInternalProfileId();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/' + this.getInternalProfileId() + '/reels/process-downloaded';
        const userData = getUserDataFromLocalStorage();

        Logger(FILE_NAME, "callProcessDownloadedApi", "", "internalProfileId", internalProfileId);

        this.setState({
            loadingModalVisible: true,
            loadingModalState: 0
        });

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) {
                reloadPage();
                return response.json();
            }
            if (response.status === 401) {
                this.setState({ failureModalVisible: true });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({ failureModalVisible: true });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "callProcessDownloadedApi", "FETCH_1", "result", result);
                this.setState({
                    loadingModalVisible: false
                });
            },
            (error) => {
                Logger(FILE_NAME, "callProcessDownloadedApi", "FETCH_1", "error", error);
                this.setState({ failureModalVisible: true });
            }
        );
    }

    // Build react-select options from this profile's own tags ([{name, count}]).
    profileTagOptions() {
        const tags = (this.state.profileDetails && this.state.profileDetails.tags) || [];
        return tags.map(t => ({
            value: t.name,
            label: t.count != null ? `${t.name} (${t.count})` : t.name,
        }));
    }

    fetchReelList() {
        const internalProfileId = this.getInternalProfileId();
        const { page, size, search, selectedTags, tagMatchMode } = this.state;
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/reels';
        const userData = getUserDataFromLocalStorage();

        const tags = selectedTags || [];
        const reqData = {
            page,
            size,
            search: search || null,
            profileId: Number(internalProfileId),
            // Only send tagFilter when at least one tag is selected; mode is AND/OR.
            tagFilter: tags.length > 0 ? { tags, mode: tagMatchMode } : null,
        };
        Logger(FILE_NAME, "fetchReelList", "", "reqData", reqData);

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ failureModalVisible: true });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({ failureModalVisible: true });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchReelList", "FETCH_2", "result", result);
                const pageData = result.data;
                this.setState({
                    reelListData: pageData.content || [],
                    totalPages: pageData.totalPages || 0,
                    totalElements: pageData.totalElements || 0,
                });
            },
            (error) => {
                Logger(FILE_NAME, "fetchReelList", "FETCH_2", "error", error);
                this.setState({ failureModalVisible: true });
            }
        );
    }

    handleSearchChange = (event) => {
        this.setState({ search: event.target.value });
    }

    handleSearchSubmit = (event) => {
        event.preventDefault();
        this.setState({ page: 1 }, () => this.fetchReelList());
    }

    handlePrevPage = () => {
        if (this.state.page > 1) {
            this.setState({ page: this.state.page - 1 }, () => this.fetchReelList());
        }
    }

    handleNextPage = () => {
        if (this.state.page < this.state.totalPages) {
            this.setState({ page: this.state.page + 1 }, () => this.fetchReelList());
        }
    }

    handleViewReel = (reelId) => {
        const userData = getUserDataFromLocalStorage();
        const fileUrl = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/reel/' + reelId + '/file';

        fetch(fileUrl, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) {
                const contentDisposition = response.headers.get('Content-Disposition') || '';
                const fileNameMatch = contentDisposition.match(/filename="(.+?)"/);
                const fileName = fileNameMatch ? fileNameMatch[1] : 'reel_' + reelId;
                return response.blob().then(blob => ({ blob, fileName }));
            }
            if (response.status === 404) {
                alert('Reel file not found. It may not have been downloaded yet.');
                throw new Error("File not found");
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            ({ blob, fileName }) => {
                const objectUrl = URL.createObjectURL(blob);
                this.setState({
                    viewReelModalVisible: true,
                    viewReelUrl: objectUrl,
                    viewReelFileName: fileName,
                });
            },
            (error) => {
                Logger(FILE_NAME, "handleViewReel", "", "error", error);
            }
        );
    }

    handleCloseReelModal = () => {
        if (this.state.viewReelUrl) {
            URL.revokeObjectURL(this.state.viewReelUrl);
        }
        this.setState({
            viewReelModalVisible: false,
            viewReelUrl: null,
            viewReelFileName: '',
        });
    }

    renderProfileReadOnly(profile) {
        return (
            <div>
                <h2 style={{ marginBottom: '8px' }}>
                    {profile.fullName || profile.username}
                    {profile.isVerified && ' ✅'}
                    &nbsp;&nbsp;
                    <CButton color="warning" size="sm" onClick={this.handleEditProfile}>✎ Edit</CButton>
                </h2>
                <p style={{ color: '#666', marginBottom: '4px' }}>@{profile.username}</p>
                <p style={{ color: '#888', marginBottom: '8px', maxWidth: '600px' }}>
                    {profile.bio || 'No bio available'}
                </p>
                <p style={{ marginBottom: '4px' }}>
                    <strong>Instagram ID:</strong> {profile.instagramId || '—'}
                </p>
                <p style={{ marginBottom: '4px' }}>
                    <strong>Followers:</strong> {profile.followersCount != null ? profile.followersCount.toLocaleString() : '—'}
                    &nbsp;&nbsp;|&nbsp;&nbsp;
                    <strong>Following:</strong> {profile.followingCount != null ? profile.followingCount.toLocaleString() : '—'}
                </p>
                <p style={{ marginBottom: '4px' }}>
                    <strong>Reels:</strong>&nbsp;
                    {profile.reelsCount ? (
                        <span>
                            <span style={{ color: '#2eb85c', fontWeight: 'bold' }} title="Downloaded reels">
                                {(profile.reelsCount.downloaded != null ? profile.reelsCount.downloaded : 0).toLocaleString()} downloaded
                            </span>
                            <span style={{ color: '#888' }}>&nbsp;|&nbsp;</span>
                            <span style={{ color: '#e55353', fontWeight: 'bold' }} title="Not-downloaded reels">
                                {(profile.reelsCount.notDownloaded != null ? profile.reelsCount.notDownloaded : 0).toLocaleString()} pending
                            </span>
                        </span>
                    ) : '—'}
                </p>
                <p style={{ marginBottom: '4px' }}>
                    <strong>Account Created:</strong> {profile.accountCreationDate || '—'}
                </p>
                <p style={{ marginBottom: '4px' }}>
                    <strong>Private:</strong> {profile.isPrivate ? 'Yes' : 'No'}
                </p>
                <p style={{ marginBottom: '4px' }}>
                    <strong>Added On:</strong> {profile.createdOn ? moment(profile.createdOn).format('YYYY/MM/DD HH:mm:ss ddd') : '—'}
                </p>
                <div style={{ marginBottom: '8px' }}>
                    <strong>🏷️ Tags:</strong>&nbsp;
                    {Array.isArray(profile.tags) && profile.tags.length > 0
                        ? profile.tags.map((t, i) => (
                            <span
                                key={'ptag-' + i}
                                style={{
                                    display: 'inline-block',
                                    background: '#edf2f7',
                                    color: '#2d3748',
                                    borderRadius: '12px',
                                    padding: '2px 10px',
                                    margin: '2px 4px 2px 0',
                                    fontSize: '12px',
                                }}
                            >
                                {t.name}
                                <span style={{ marginLeft: '6px', color: '#718096', fontWeight: 'bold' }}>
                                    {t.count}
                                </span>
                            </span>
                        ))
                        : <span style={{ color: '#888' }}>—</span>}
                </div>
                {profile.link && (
                    <a href={profile.link} target="_blank" rel="noopener noreferrer">
                        Visit Profile →
                    </a>
                )}
                {profile.externalUrl && (
                    <span>&nbsp;&nbsp;|&nbsp;&nbsp;
                        <a href={profile.externalUrl} target="_blank" rel="noopener noreferrer">
                            External Link →
                        </a>
                    </span>
                )}
            </div>
        );
    }

    renderProfileEditForm(profile) {
        const form = this.state.editForm;
        const labelStyle = { fontWeight: 'bold', marginBottom: '2px', display: 'block' };
        const rowStyle = { marginBottom: '8px', maxWidth: '600px' };

        return (
            <div>
                <h2 style={{ marginBottom: '12px' }}>
                    Editing @{profile.username}
                </h2>

                <div style={rowStyle}>
                    <label style={labelStyle}>Full Name</label>
                    <CInput type="text" value={form.fullName} onChange={this.handleEditFormChange('fullName')} />
                </div>
                <div style={rowStyle}>
                    <label style={labelStyle}>Instagram ID</label>
                    <CInput type="text" value={form.instagramId} onChange={this.handleEditFormChange('instagramId')} />
                </div>
                <div style={rowStyle}>
                    <label style={labelStyle}>Bio</label>
                    <CInput type="text" value={form.bio} onChange={this.handleEditFormChange('bio')} />
                </div>
                <div style={rowStyle}>
                    <label style={labelStyle}>Followers Count</label>
                    <CInput type="number" value={form.followersCount} onChange={this.handleEditFormChange('followersCount')} />
                </div>
                <div style={rowStyle}>
                    <label style={labelStyle}>Following Count</label>
                    <CInput type="number" value={form.followingCount} onChange={this.handleEditFormChange('followingCount')} />
                </div>
                <div style={rowStyle}>
                    <label style={labelStyle}>Account Creation Date</label>
                    <CInput type="text" value={form.accountCreationDate} onChange={this.handleEditFormChange('accountCreationDate')} />
                </div>

                <div className="mt-3">
                    <CButton color="success" disabled={this.state.savingProfile} onClick={this.handleSaveProfile}>
                        {this.state.savingProfile ? 'Saving…' : '💾 Save'}
                    </CButton>
                    &nbsp;
                    <CButton color="secondary" disabled={this.state.savingProfile} onClick={this.handleCancelEditProfile}>
                        Cancel
                    </CButton>
                </div>
            </div>
        );
    }

    renderProfileDetails() {
        const profile = this.state.profileDetails;
        if (!profile) return null;

        return (
            <CCard className="mb-4">
                <CCardBody>
                    <CRow className="align-items-center">
                        <CCol md="2" className="text-center">
                            {profile.profilePicBase64 && (
                                <img
                                    src={'data:image/jpeg;base64,' + profile.profilePicBase64}
                                    alt={profile.username}
                                    style={{ width: '100%', aspectRatio: '1 / 1', objectFit: 'cover' }}
                                />
                            )}
                            <input
                                type="file"
                                accept="image/*"
                                ref={(el) => { this.profilePicInputRef = el; }}
                                style={{ display: 'none' }}
                                onChange={this.handleProfilePicSelected}
                            />
                            <CButton
                                color="primary"
                                size="sm"
                                className="mt-2"
                                disabled={this.state.uploadingProfilePic}
                                onClick={() => this.profilePicInputRef && this.profilePicInputRef.click()}
                            >
                                {this.state.uploadingProfilePic ? 'Uploading…' : 'Update Pic'}
                            </CButton>
                        </CCol>
                        <CCol md="10">
                            {this.state.editingProfile
                                ? this.renderProfileEditForm(profile)
                                : this.renderProfileReadOnly(profile)}
                        </CCol>
                    </CRow>
                </CCardBody>
            </CCard>
        );
    }

    render() {
        Logger(FILE_NAME, "render", "", "this.state", this.state);

        return (
            this.state.isLoaded ?
            <div>
                <h1>Instagram Profile Details &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
                    <CButton color="secondary" className="px-4" onClick={() => this.props.history.goBack()}>← Back</CButton>
                    &nbsp;
                    <CButton color="success" className="px-4" onClick={this.reloadData}>Refresh</CButton>
                </h1>
                <br />

                {/* Profile details card */}
                {this.renderProfileDetails()}

                {/* Reels section */}
                <h3>Reels ({this.state.totalElements})
                    &nbsp;&nbsp;
                    <CButton
                        color="dark"
                        size="sm"
                        onClick={() => this.props.history.push('/instagram/reels/viewer/' + this.getInternalProfileId())}
                    >
                        ▶ View Reels
                    </CButton>
                    &nbsp;&nbsp;
                    <CButton
                        color="dark"
                        size="sm"
                        onClick={() => this.props.history.push('/instagram/reels/viewer/' + this.getInternalProfileId() + '?random=true')}
                    >
                        🔀 Shuffle Reels
                    </CButton>
                    &nbsp;&nbsp;
                    <CButton
                        color="dark"
                        size="sm"
                        onClick={() => this.callProcessDownloadedApi()}
                    >
                        ↻ process-downloaded from yt-dl
                    </CButton>
                </h3>
                <br />

                {/* Search bar */}
                <CContainer className="mb-3">
                    <CRow className="justify-content-center">
                        <CCol md="6">
                            <form onSubmit={this.handleSearchSubmit}>
                                <CInputGroup>
                                    <CInputGroupPrepend>
                                        <CInputGroupText>🔍</CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="Search reels (caption, shortcode, link)..."
                                        type="text"
                                        value={this.state.search}
                                        onChange={this.handleSearchChange}
                                    />
                                    <CButton color="primary" type="submit" className="ml-2">Search</CButton>
                                </CInputGroup>
                            </form>
                        </CCol>
                    </CRow>

                    {/* Tag filter: searchable multi-select of this profile's tags */}
                    <CRow className="justify-content-center mt-2">
                        <CCol md="6">
                            <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                                <span style={{ fontSize: '1.2em' }} title="Filter reels by this profile's tags">🏷️</span>
                                <div style={{ flex: 1 }}>
                                    <Select
                                        isMulti
                                        placeholder="Filter by tags…"
                                        options={this.profileTagOptions()}
                                        value={this.profileTagOptions().filter(o => this.state.selectedTags.includes(o.value))}
                                        onChange={(choices) => this.setState(
                                            { selectedTags: (choices || []).map(o => o.value) },
                                            () => this.setState({ page: 1 }, () => this.fetchReelList())
                                        )}
                                        noOptionsMessage={() => 'No tags on this profile'}
                                        menuPortalTarget={document.body}
                                        styles={{ menuPortal: base => ({ ...base, zIndex: 9999 }) }}
                                    />
                                </div>
                                <select
                                    className="form-control"
                                    style={{ maxWidth: '120px' }}
                                    value={this.state.tagMatchMode}
                                    onChange={(e) => this.setState(
                                        { tagMatchMode: e.target.value },
                                        () => { if (this.state.selectedTags.length > 0) this.setState({ page: 1 }, () => this.fetchReelList()); }
                                    )}
                                    title="OR = reels with any of the tags; AND = reels with all tags"
                                >
                                    <option value="OR">Any (OR)</option>
                                    <option value="AND">All (AND)</option>
                                </select>
                            </div>
                        </CCol>
                    </CRow>
                </CContainer>

                {/* Reels table */}
                <MaterialReactTable
                    initialState={{ density: 'compact' }}
                    columns={reelTableColumnData}
                    data={this.state.reelListData}
                    enablePagination={false}
                    enableEditing={false}
                    enableRowActions={true}
                    positionActionsColumn="first"
                    renderRowActions={({ row }) => (
                        <CButton
                            color="info"
                            size="sm"
                            disabled={!row.original.downloaded}
                            onClick={() => this.props.history.push(
                                '/instagram/reels/viewer/' + this.getInternalProfileId()
                                + '?startPage=' + this.state.page
                                + '&startReelId=' + row.original.id
                            )}
                        >
                            ▶ View
                        </CButton>
                    )}
                />

                {/* Pagination controls */}
                <CContainer className="mt-3">
                    <CRow className="justify-content-center align-items-center">
                        <CCol md="6" className="text-center">
                            <CButton
                                color="secondary"
                                disabled={this.state.page <= 1}
                                onClick={this.handlePrevPage}
                            >
                                ← Prev
                            </CButton>
                            &nbsp;&nbsp;
                            <span>
                                Page <strong>{this.state.page}</strong> of <strong>{this.state.totalPages}</strong>
                                &nbsp;({this.state.totalElements} total reels)
                            </span>
                            &nbsp;&nbsp;
                            <CButton
                                color="secondary"
                                disabled={this.state.page >= this.state.totalPages}
                                onClick={this.handleNextPage}
                            >
                                Next →
                            </CButton>
                        </CCol>
                    </CRow>
                </CContainer>

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />

                {/* View Reel Modal */}
                <Modal
                    isOpen={this.state.viewReelModalVisible}
                    toggle={this.handleCloseReelModal}
                    size="lg"
                    centered
                >
                    <ModalHeader toggle={this.handleCloseReelModal}>
                        {this.state.viewReelFileName || 'View Reel'}
                    </ModalHeader>
                    <ModalBody className="text-center">
                        {this.state.viewReelUrl && (
                            <video
                                src={this.state.viewReelUrl}
                                controls
                                autoPlay
                                style={{ maxWidth: '100%', maxHeight: '70vh', borderRadius: '8px' }}
                            />
                        )}
                    </ModalBody>
                </Modal>
            </div>
            : <Loading />
        );
    }
}

export default InstagramProfile;
